-- Stage 2.1.8: a "4K" Pick rules preset for a second Version of a movie
-- (pick-rules.md: 4K via Versions). Must match domain.FourK(); a test checks it.
INSERT INTO pick_rules (created_at, created_by, updated_at, updated_by, name, kinds, revision, preset, body)
SELECT strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), '{"kind":"system"}', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), '{"kind":"system"}',
       '4K', '["movie","show"]', 1, 1,
       '{"steps":[{"quality":"cam","allowed":false},{"quality":"telesync","allowed":false},{"quality":"sd_tv","allowed":false},{"quality":"sd_dvd","allowed":false},{"quality":"720p_tv","allowed":false},{"quality":"720p_web","allowed":false},{"quality":"720p_bluray","allowed":false},{"quality":"1080p_tv","allowed":false},{"quality":"1080p_web","allowed":false},{"quality":"1080p_bluray","allowed":false},{"quality":"1080p_remux","allowed":false},{"quality":"2160p_web","allowed":true},{"quality":"2160p_bluray","allowed":true},{"quality":"2160p_remux","allowed":true}],"good_enough_at":"2160p_web","traits":[{"trait":"dv","points":20},{"trait":"hdr10plus","points":15},{"trait":"hdr10","points":10},{"trait":"atmos","points":10},{"trait":"hevc","points":5},{"trait":"upscaled","points":-100}],"must_have":[],"never":["sample","executable","password_protected","disc_image","hardcoded_subs","3d","cam","telesync"],"min_points":0,"size_limits":{"*":{"min":53687091,"max":1073741824,"per_minute":true}},"protocol":{"prefer":"either","wait_minutes_torrent":0,"wait_minutes_usenet":0,"skip_wait_at_good_enough":false},"language":{"wanted":[],"original_ok":true},"order":"quality_then_points","upgrade_min_points":10,"proper_policy":{"mode":"take_any"}}'
WHERE NOT EXISTS (SELECT 1 FROM pick_rules WHERE name = '4K');
